if (points.empty() || k == 0) {
    return {};
}

std::vector<std::pair<double, size_t>> distances;
distances.reserve(points.size());

// Calculate squared distances to avoid sqrt operation
for (size_t i = 0; i < points.size(); ++i) {
    double dx = points[i].x - searchPoint.x;
    double dy = points[i].y - searchPoint.y;
    double dz = points[i].z - searchPoint.z;
    double distSq = dx*dx + dy*dy + dz*dz;
    distances.emplace_back(distSq, i);
}

// Sort by distance
std::sort(distances.begin(), distances.end(),
    [](const std::pair<double, size_t>& a, const std::pair<double, size_t>& b) {
        return a.first < b.first;
    });

// Extract k nearest neighbors
std::vector<size_t> result;
result.reserve(std::min(k, distances.size()));
for (size_t i = 0; i < std::min(k, distances.size()); ++i) {
    result.push_back(distances[i].second);
}

return result;

